window.QUIZ_BANK=[{"id":"pc-u1-1.1","course":"pc","unit":"u1","title":"Topic 1.1 · Change in Tandem","kind":"quiz","minutes":null,"lesson":"1.1","items":[{"q":"The table gives values of $f$. Which statement is consistent with the table? <div class=\"tbl\"><table><tr><td>$x$</td><td>$0$</td><td>$2$</td><td>$4$</td><td>$6$</td><td>$8$</td></tr><tr><td>$f(x)$</td><td>$3$</td><td>$8$</td><td>$11$</td><td>$12$</td><td>$12.5$</td></tr></table></div>","c":["$f$ is increasing and concave up.","$f$ is increasing and concave down.","$f$ is decreasing and concave up.","$f$ is decreasing and concave down."],"a":1,"e":"Outputs increase; the changes $5,3,1,0.5$ decrease, so the rate of change is decreasing: concave down.","calc":false,"topic":"","img":[]},{"q":"The graph of $g$ is shown. On which interval is $g$ decreasing and concave up?","c":["$(-1,0)$","$(0,1)$","$(1,2)$","$(-2,-1)$"],"a":1,"e":"$g(x)=x^3-3x$ decreases on $(-1,1)$. It is concave up to the right of $x=0$. Both hold on $(0,1)$.","calc":false,"topic":"","img":["2f106779b30b.svg"]},{"q":"Which statement must be true if the rate of change of $h$ is negative and increasing on an interval?","c":["$h$ is increasing and concave down.","$h$ is decreasing and concave down.","$h$ is decreasing and concave up.","$h$ is increasing and concave up."],"a":2,"e":"Negative rate of change: decreasing. Increasing rate of change: concave up.","calc":false,"topic":"","img":[]},{"q":"What are the zeros of $p(x)=x(x-3)(2x+5)$?","c":["$0,\\ 3,\\ 5$","$0,\\ -3,\\ \\frac52$","$3,\\ -\\frac52$","$0,\\ 3,\\ -\\frac52$"],"a":3,"e":"Set each factor equal to $0$: $x=0$, $x=3$, $2x+5=0\\Rightarrow x=-\\frac52$.","calc":false,"topic":"","img":[]}]},{"id":"pc-u1-1.2","course":"pc","unit":"u1","title":"Topic 1.2 · Rates of Change","kind":"quiz","minutes":null,"lesson":"1.2","items":[{"q":"What is the average rate of change of $f(x)=2x^2-3$ on $[1,4]$?","c":["$10$","$15$","$30$","$8$"],"a":0,"e":"$f(4)=29$, $f(1)=-1$: $\\frac{30}{3}=10$.","calc":false,"topic":"","img":[]},{"q":"What is the average rate of change of $g(x)=x^3-2x$ on $[-1,2]$?","c":["$3$","$\\dfrac53$","$1$","$-1$"],"a":2,"e":"$g(2)=4$, $g(-1)=1$: $\\frac{3}{3}=1$.","calc":false,"topic":"","img":[]},{"q":"What is the average rate of change of $h(x)=\\dfrac{12}{x}$ on $[2,6]$?","c":["$-1$","$-4$","$1$","$-\\dfrac12$"],"a":0,"e":"$h(6)=2$, $h(2)=6$: $\\frac{2-6}{4}=-1$.","calc":false,"topic":"","img":[]},{"q":"The average rate of change of $f(x)=x^2+kx$ on $[0,2]$ is $5$. What is $k$?","c":["$1$","$5$","$3$","$7$"],"a":2,"e":"$\\frac{f(2)-f(0)}{2}=\\frac{4+2k}{2}=2+k=5$, so $k=3$.","calc":false,"topic":"","img":[]},{"q":"The table gives values of $g$. What is the average rate of change of $g$ on $[2,8]$? <div class=\"tbl\"><table><tr><td>$x$</td><td>$2$</td><td>$4$</td><td>$6$</td><td>$8$</td></tr><tr><td>$g(x)$</td><td>$-3$</td><td>$1$</td><td>$6$</td><td>$9$</td></tr></table></div>","c":["$12$","$2$","$\\dfrac12$","$6$"],"a":1,"e":"$\\frac{9-(-3)}{8-2}=\\frac{12}{6}=2$.","calc":false,"topic":"","img":[]},{"q":"The graph of $h$ consists of line segments. What is the average rate of change of $h$ on $[1,5]$?","c":["$-\\dfrac32$","$-6$","$\\dfrac32$","$-1$"],"a":0,"e":"$h(1)=5$, $h(5)=-1$: $\\frac{-1-5}{4}=-\\frac32$.","calc":false,"topic":"","img":["af537e31cf83.svg"]},{"q":"Using the same graph of $h$, on which interval is the average rate of change of $h$ equal to $-1$?","c":["$[0,3]$","$[3,6]$","$[1,3]$","$[0,6]$"],"a":0,"e":"$h(0)=4$, $h(3)=1$: $\\frac{1-4}{3}=-1$. The others: $[3,6]$: $\\frac13$; $[1,3]$: $-2$; $[0,6]$: $-\\frac13$.","calc":false,"topic":"","img":["af537e31cf83.svg"]},{"q":"$V(t)$ is the volume of water in a tank, in liters, $t$ minutes after a valve opens. What are the units of the average rate of change of $V$?","c":["minutes per liter","liters","liters per minute","liters times minutes"],"a":2,"e":"Output units per input unit.","calc":false,"topic":"","img":[]},{"q":"The population of a town was $12{,}400$ in 2010 and $15{,}100$ in 2019. Which is the average rate of change of the population over this period?","c":["$270$ people per year","$300$ people per year","$2700$ people per year","$337.5$ people per year"],"a":1,"e":"$\\frac{15100-12400}{9}=\\frac{2700}{9}=300$.","calc":false,"topic":"","img":[]},{"q":"A car's distance from home is $D(t)$ km, $t$ hours after noon. $D(1)=80$ and $D(3)=20$. Which is the best interpretation of $\\frac{D(3)-D(1)}{3-1}$?","c":["The car traveled 30 km.","Between 1 p.m. and 3 p.m., the car's distance from home decreased on average by 30 km per hour.","At 3 p.m. the car was moving at 30 km per hour.","The car was 30 km from home at 2 p.m."],"a":1,"e":"The value is $-30$ km/h: an average rate over the interval, not a value at an instant.","calc":false,"topic":"","img":[]},{"q":"Using the interval $[2,\\,2.001]$, which is the best estimate of the rate of change of $f(x)=x^2+x$ at $x=2$?","c":["$4$","$6$","$2.5$","$5$"],"a":3,"e":"$\\frac{f(2.001)-f(2)}{0.001}=\\frac{6.005001-6}{0.001}=5.001$.","calc":false,"topic":"","img":[]},{"q":"The function $g$ changes from increasing to decreasing at $x=3$. Which must be true about the rate of change of $g$ at $x=3$?","c":["It changes from negative to positive.","It changes from positive to negative.","It is undefined.","It is the greatest value of $g$."],"a":1,"e":"Increasing means positive rate of change; decreasing means negative.","calc":false,"topic":"","img":[]},{"q":"Which is the best estimate of the rate of change of $f(x)=\\sqrt{x}$ at $x=4$?","c":["$0.125$","$0.25$","$0.5$","$2$"],"a":1,"e":"$\\frac{\\sqrt{4.001}-2}{0.001}\\approx0.24998$, and from the left $\\approx0.25002$: about $0.25$.","calc":true,"topic":"","img":[]}]},{"id":"pc-u1-1.3","course":"pc","unit":"u1","title":"Topic 1.3 · Rates of Change in Linear and Quadratic Functions","kind":"quiz","minutes":null,"lesson":"1.3","items":[{"q":"Each list gives outputs at $x=0,1,2,3$. Which list could come from a linear function?","c":["$3,5,9,15$","$4,7,10,13$","$1,2,4,8$","$2,3,5,8$"],"a":1,"e":"Constant differences of $3$.","calc":false,"topic":"","img":[]},{"q":"Each list gives outputs at $x=0,1,2,3,4$. Which list could come from a quadratic function?","c":["$1,3,9,27,81$","$5,8,11,14,17$","$0,2,8,18,32$","$1,2,4,7,13$"],"a":2,"e":"Differences $2,6,10,14$; second differences $4,4,4$ ($y=2x^2$).","calc":false,"topic":"","img":[]},{"q":"For $f(x)=ax^2+bx+c$, the second differences of $f(0),f(1),f(2),\\dots$ are all $-4$. What is $a$?","c":["$-4$","$4$","$-2$","$2$"],"a":2,"e":"Second difference $=2a$ for step 1.","calc":false,"topic":"","img":[]},{"q":"The inputs in a table are $0,2,4,6$ and the outputs of a quadratic function have second differences equal to $8$. What is $a$?","c":["$1$","$2$","$4$","$8$"],"a":0,"e":"With step $h=2$, second differences equal $2ah^2=8a$. So $8a=8$ and $a=1$.","calc":false,"topic":"","img":[]},{"q":"The graph of a quadratic $f$ is shown. What is the average rate of change of $f$ on $[1,3]$?","c":["$-2$","$4$","$2$","$0$"],"a":2,"e":"$f(1)=-4$, $f(3)=0$: $\\frac{4}{2}=2$.","calc":false,"topic":"","img":["11bae2930da7.svg"]},{"q":"For the same function, the average rate of change on $[-1,1]$ is $-2$ and on $[1,3]$ is $2$. Which statement explains this?","c":["$f$ is linear.","The rate of change of $f$ is increasing, so the graph is concave up.","The rate of change of $f$ is decreasing.","$f$ has a maximum at $x=1$."],"a":1,"e":"Average rates over consecutive equal intervals increase: concave up. The vertex $(1,-4)$ is a minimum.","calc":false,"topic":"","img":[]},{"q":"At what value of $x$ does the rate of change of $f(x)=3x^2-12x+1$ change from negative to positive?","c":["$x=2$","$x=-2$","$x=4$","$x=12$"],"a":0,"e":"Vertex at $x=\\frac{12}{6}=2$, and $a>0$.","calc":false,"topic":"","img":[]}]},{"id":"pc-u1-1.4","course":"pc","unit":"u1","title":"Topic 1.4 · Polynomial Functions and Rates of Change","kind":"quiz","minutes":null,"lesson":"1.4","items":[{"q":"What is the greatest possible number of local extrema of a polynomial of degree 5?","c":["$5$","$4$","$3$","$6$"],"a":1,"e":"At most $n-1$.","calc":false,"topic":"","img":[]},{"q":"What is the degree and leading coefficient of $p(x)=-3x(x+2)^2(1-x)$?","c":["degree 4, leading coefficient $-3$","degree 4, leading coefficient $3$","degree 3, leading coefficient $3$","degree 5, leading coefficient $-3$"],"a":1,"e":"Leading term $-3x\\cdot x^2\\cdot(-x)=3x^4$.","calc":false,"topic":"","img":[]},{"q":"The graph of $p(x)=\\frac14x^4-2x^2$ is shown. What is the absolute minimum value of $p$?","c":["$0$","$-2$","$-5$","$-4$"],"a":3,"e":"Local minima $(\\pm2,-4)$ are the lowest points.","calc":false,"topic":"","img":["58a4791b2ba0.svg"]},{"q":"Using the same graph, what is the absolute maximum of $p$ on $[-1,3]$?","c":["$0$","$2.25$","$-1.75$","$4$"],"a":1,"e":"Compare $p(-1)=-1.75$, $p(0)=0$, $p(2)=-4$, $p(3)=20.25-18=2.25$.","calc":false,"topic":"","img":["58a4791b2ba0.svg"]}]},{"id":"pc-u1-1.5","course":"pc","unit":"u1","title":"Topic 1.5 · Polynomial Functions and Complex Zeros","kind":"quiz","minutes":null,"lesson":"1.5","items":[{"q":"What are the zeros of $p(x)=x^2(x-4)(x+1)$?","c":["$0,\\ 4,\\ -1$","$0,\\ -4,\\ 1$","$4,\\ -1$","$2,\\ 4,\\ -1$"],"a":0,"e":"Set each factor to $0$.","calc":false,"topic":"","img":[]},{"q":"$p(3)=0$ for a polynomial $p$. Which must be true?","c":["$(x+3)$ is a factor of $p(x)$.","$(x-3)$ is a factor of $p(x)$.","$p(0)=3$.","$p$ has degree 3."],"a":1,"e":"A zero $a$ corresponds to the factor $(x-a)$.","calc":false,"topic":"","img":[]},{"q":"Which polynomial has $x$-intercepts at $-2$, $1$ and $5$ only?","c":["$(x-2)(x+1)(x+5)$","$(x+2)(x-1)(x-5)$","$(x+2)(x-1)(x+5)$","$x(x+2)(x-1)(x-5)$"],"a":1,"e":"The factors $(x+2)$, $(x-1)$, $(x-5)$ give zeros $-2,1,5$. Choice (D) also has the intercept $0$.","calc":false,"topic":"","img":[]},{"q":"Which describes the graph of $p(x)=(x+2)^2(x-1)$ at $x=-2$?","c":["It has a vertical asymptote.","It crosses the $x$-axis.","It touches the $x$-axis without crossing it.","It has a hole."],"a":2,"e":"Even multiplicity.","calc":false,"topic":"","img":[]},{"q":"The graph of a cubic $q$ is shown; it passes through $(0,2)$. Which could be $q(x)$?","c":["$(x+2)(x-1)^2$","$(x-2)(x+1)^2$","$(x+2)^2(x-1)$","$-(x+2)(x-1)^2$"],"a":0,"e":"Crosses at $-2$, touches at $1$, rises to the right; $q(0)=2$.","calc":false,"topic":"","img":["a4774ee74888.svg"]},{"q":"At which $x$-intercept does the graph of $p(x)=x^3(x-2)^2(x+4)$ flatten out as it crosses the axis?","c":["$x=0$","$x=2$","$x=-4$","none"],"a":0,"e":"Multiplicity 3 (odd, at least 3).","calc":false,"topic":"","img":[]},{"q":"How many complex zeros, counted with multiplicity, does $p(x)=x^6-2x^3+5$ have?","c":["$3$","$5$","$6$","$2$"],"a":2,"e":"Degree 6.","calc":false,"topic":"","img":[]},{"q":"A polynomial with real coefficients has zeros $2$ and $1+3i$. Which must also be a zero?","c":["$-2$","$3+i$","$-1-3i$","$1-3i$"],"a":3,"e":"Conjugate pairs.","calc":false,"topic":"","img":[]},{"q":"What are the zeros of $p(x)=x^3+4x$?","c":["$0,\\ 2,\\ -2$","$0,\\ 2i,\\ -2i$","$0,\\ 4i$","$0$ only"],"a":1,"e":"$x(x^2+4)$.","calc":false,"topic":"","img":[]},{"q":"A polynomial of degree 5 with real coefficients has exactly two non-real zeros. How many real zeros (counted with multiplicity) does it have?","c":["$1$","$2$","$3$","$5$"],"a":2,"e":"$5-2=3$.","calc":false,"topic":"","img":[]},{"q":"A polynomial with real coefficients has zeros $3$ and $2i$. What is its least possible degree?","c":["$2$","$3$","$4$","$6$"],"a":1,"e":"$-2i$ is also a zero.","calc":false,"topic":"","img":[]},{"q":"Which polynomial has real coefficients and zeros $1$ and $i$?","c":["$(x-1)(x-i)$","$(x-1)(x^2+1)$","$(x+1)(x^2+1)$","$(x-1)(x^2-1)$"],"a":1,"e":"$(x-i)(x+i)=x^2+1$.","calc":false,"topic":"","img":[]},{"q":"Which function is even?","c":["$x^3-x$","$x^4+3x^2-1$","$x^2+x$","$(x-1)^2$"],"a":1,"e":"Only even powers.","calc":false,"topic":"","img":[]},{"q":"Which function is odd?","c":["$x^4+x$","$x^3+1$","$x^3-5x$","$|x|$"],"a":2,"e":"$f(-x)=-f(x)$.","calc":false,"topic":"","img":[]},{"q":"The graph of an odd function passes through $(3,-7)$. Which point must also be on the graph?","c":["$(-3,-7)$","$(3,7)$","$(-3,7)$","$(7,-3)$"],"a":2,"e":"Symmetric about the origin: $f(-3)=-f(3)=7$.","calc":false,"topic":"","img":[]}]},{"id":"pc-u1-1.6","course":"pc","unit":"u1","title":"Topic 1.6 · Polynomial Functions and End Behavior","kind":"quiz","minutes":null,"lesson":"1.6","items":[{"q":"$\\displaystyle\\lim_{x\\to\\infty}\\left(-4x^3+x^2\\right)$ is","c":["$\\infty$","$-\\infty$","$-4$","$0$"],"a":1,"e":"Odd degree, negative leading coefficient.","calc":false,"topic":"","img":[]},{"q":"Let $p(x)=(2-x)^3$. What is $\\displaystyle\\lim_{x\\to-\\infty}p(x)$?","c":["$-\\infty$","$\\infty$","$8$","$0$"],"a":1,"e":"Leading term $-x^3$.","calc":false,"topic":"","img":[]},{"q":"Which polynomial increases without bound at both ends?","c":["$x^3+1$","$-x^4$","$5x-x^2$","$2x^6-x$"],"a":3,"e":"Even degree, positive leading coefficient.","calc":false,"topic":"","img":[]},{"q":"The graph of a polynomial $r$ with zeros $\\pm1$, $\\pm2$ and $r(0)=-2$ is shown. Which could be $r(x)$?","c":["$x^4-5x^2+4$","$-x^3+4x$","$-\\frac12\\left(x^4-5x^2+4\\right)$","$\\frac12\\left(x^4-5x^2+4\\right)$"],"a":2,"e":"Both ends down; correct zeros; $r(0)=-2$.","calc":false,"topic":"","img":["49599072ea60.svg"]}]},{"id":"pc-u1-R1.1-1.6","course":"pc","unit":"u1","title":"Review 1.1-1.6 · Review of Topics 1.1 to 1.6","kind":"quiz","minutes":null,"lesson":"R1.1-1.6","items":[{"q":"What is the average rate of change of $f(x)=x^3-x$ on $[0,2]$?","c":["$6$","$3$","$2$","$4$"],"a":1,"e":"$f(2)=6$, $f(0)=0$: $\\frac62=3$.","calc":false,"topic":"1.2","img":[]},{"q":"Outputs at $x=0,1,2,3,4$ are $1,4,9,16,25$. Which model fits?","c":["linear","quadratic","cubic","none"],"a":1,"e":"Second differences $2$.","calc":false,"topic":"1.3","img":[]},{"q":"A polynomial with real coefficients has degree 3 and zeros $4$ and $-i$. What is the third zero?","c":["$-4$","$i$","$4i$","$0$"],"a":1,"e":"Conjugate of $-i$.","calc":false,"topic":"1.5","img":[]},{"q":"Which is $\\displaystyle\\lim_{x\\to-\\infty}\\left(3x^4-x^5\\right)$?","c":["$-\\infty$","$\\infty$","$3$","$0$"],"a":1,"e":"Leading term $-x^5$; as $x\\to-\\infty$, $-x^5\\to\\infty$.","calc":false,"topic":"1.6","img":[]},{"q":"How many turning points can a polynomial of degree 4 have?","c":["only 3","1 or 3","0, 1, 2 or 3","4"],"a":1,"e":"A degree-4 polynomial has at least one and at most three turning points, and the number is odd (end behaviors match). So 1 or 3.","calc":false,"topic":"1.4","img":[]},{"q":"The graph of $f$ is shown. On which interval is $f$ increasing and concave up?","c":["$(0,1)$","$(1,2)$","$(2,\\infty)$","$(-\\infty,0)$"],"a":2,"e":"$f(x)=x^2(x-3)$ increases on $(-\\infty,0)$ and $(2,\\infty)$; concave up for $x>1$.","calc":false,"topic":"1.1 \\textbullet\\ graph","img":["6dd28fa201e0.svg"]},{"q":"Using the same graph, what is the average rate of change of $f$ on $[1,3]$?","c":["$-2$","$0$","$2$","$1$"],"a":3,"e":"$f(1)=-2$, $f(3)=0$: $\\frac{2}{2}=1$.","calc":false,"topic":"1.2 \\textbullet\\ graph","img":["6dd28fa201e0.svg"]},{"q":"Which could be the polynomial graphed above?","c":["$x(x-3)^2$","$-x^2(x-3)$","$x^2(x-3)$","$x^2(x+3)$"],"a":2,"e":"Touches at $0$, crosses at $3$, rises to the right.","calc":false,"topic":"1.5","img":["6dd28fa201e0.svg"]},{"q":"For $g(x)=-2x^2+8x-1$, on which interval is $g$ increasing?","c":["$(-\\infty,2)$","$(2,\\infty)$","$(-\\infty,-2)$","$(-2,\\infty)$"],"a":0,"e":"Vertex $x=-\\frac{8}{-4}=2$; $a<0$, so increasing before the vertex.","calc":false,"topic":"1.3","img":[]},{"q":"$P(t)$ is the number of bacteria after $t$ hours, $P(2)=500$, $P(5)=1400$. What is the average rate of change of $P$ on $[2,5]$?","c":["$300$ bacteria per hour","$900$ bacteria per hour","$280$ bacteria per hour","$180$ bacteria per hour"],"a":0,"e":"$\\frac{900}{3}=300$.","calc":false,"topic":"1.2","img":[]},{"q":"A polynomial is increasing on $(-\\infty,-1)$, decreasing on $(-1,4)$ and increasing on $(4,\\infty)$. Which is true?","c":["local maximum at $x=4$","local minimum at $x=-1$","local maximum at $x=-1$","no local extrema"],"a":2,"e":"Increasing to decreasing at $x=-1$.","calc":false,"topic":"1.4","img":[]},{"q":"What is the multiplicity of the zero $x=-2$ of $p(x)=(x^2-4)^2(x+2)$?","c":["$1$","$2$","$3$","$5$"],"a":2,"e":"$(x^2-4)^2=(x-2)^2(x+2)^2$, times $(x+2)$: $(x+2)^3$.","calc":false,"topic":"1.5","img":[]},{"q":"Which describes the end behavior of $p(x)=-x^2(x-1)(x+5)^2$?","c":["up on both ends","down on both ends","up on the left, down on the right","down on the left, up on the right"],"a":2,"e":"Leading term $-x^5$.","calc":false,"topic":"1.6","img":[]}]},{"id":"pc-u1-1.7","course":"pc","unit":"u1","title":"Topic 1.7 · Rational Functions and End Behavior","kind":"quiz","minutes":null,"lesson":"1.7","items":[{"q":"What is the horizontal asymptote of $r(x)=\\dfrac{5x-1}{x^2+4}$?","c":["$y=5$","$y=0$","$y=-\\frac14$","There is none."],"a":1,"e":"Degree of numerator $<$ degree of denominator.","calc":false,"topic":"","img":[]},{"q":"What is the horizontal asymptote of $r(x)=\\dfrac{4x^3-x}{1-2x^3}$?","c":["$y=2$","$y=4$","$y=-2$","$y=0$"],"a":2,"e":"$\\frac{4}{-2}=-2$.","calc":false,"topic":"","img":[]},{"q":"What is the slant asymptote of $r(x)=\\dfrac{x^2+3x}{x-1}$?","c":["$y=x+3$","$y=x+4$","$y=x$","$y=x-4$"],"a":1,"e":"$x^2+3x=(x-1)(x+4)+4$.","calc":false,"topic":"","img":[]},{"q":"$\\displaystyle\\lim_{x\\to-\\infty}\\frac{x^3}{x^2+1}$ is","c":["$1$","$0$","$\\infty$","$-\\infty$"],"a":3,"e":"Behaves like $x$.","calc":false,"topic":"","img":[]},{"q":"The graph of $r(x)=\\dfrac{-2x^2}{x^2+1}$ is shown. What is $\\displaystyle\\lim_{x\\to\\infty}r(x)$?","c":["$0$","$-2$","$-\\infty$","$2$"],"a":1,"e":"The graph levels off at $y=-2$.","calc":false,"topic":"","img":["fa33ffc7608d.svg"]}]},{"id":"pc-u1-1.8","course":"pc","unit":"u1","title":"Topic 1.8 · Rational Functions and Zeros","kind":"quiz","minutes":null,"lesson":"1.8","items":[{"q":"What are the zeros of $r(x)=\\dfrac{x^2-9}{x+2}$?","c":["$-2$","$3$ and $-3$","$9$","$3$ only"],"a":1,"e":"Neither $\\pm3$ is excluded.","calc":false,"topic":"","img":[]},{"q":"What are the zeros of $r(x)=\\dfrac{x^2-4x}{x-4}$?","c":["$0$ and $4$","$4$ only","$0$ only","none"],"a":2,"e":"$x=4$ is excluded.","calc":false,"topic":"","img":[]},{"q":"What is the solution set of $\\dfrac{x+2}{x-1}<0$?","c":["$(-\\infty,-2)$","$(1,\\infty)$","$(-\\infty,-2)\\cup(1,\\infty)$","$(-2,1)$"],"a":3,"e":"Test $x=0$: negative.","calc":false,"topic":"","img":[]},{"q":"What is the solution set of $\\dfrac{x-3}{x+1}\\ge0$?","c":["$(-\\infty,-1]\\cup[3,\\infty)$","$[3,\\infty)$","$(-1,3]$","$(-\\infty,-1)\\cup[3,\\infty)$"],"a":3,"e":"Include $x=3$, exclude $x=-1$.","calc":false,"topic":"","img":[]},{"q":"The graph of $r(x)=\\frac{(x+3)(x-2)}{x^2}$ is shown. Solve $r(x)>0$.","c":["$(-3,2)$","$(-3,0)\\cup(0,2)$","$(-\\infty,-3)\\cup(2,\\infty)$","$(2,\\infty)$"],"a":2,"e":"Above the axis left of $-3$ and right of $2$.","calc":false,"topic":"","img":["033c19c95f68.svg"]}]},{"id":"pc-u1-1.9-1.10","course":"pc","unit":"u1","title":"Topic 1.9-1.10 · Rational Functions and Asymptotes","kind":"quiz","minutes":null,"lesson":"1.9-1.10","items":[{"q":"Which line is a vertical asymptote of $r(x)=\\dfrac{x+2}{x^2-x-6}$?","c":["$x=-2$","$x=3$","$x=-2$ and $x=3$","$x=6$"],"a":1,"e":"$(x+2)$ cancels (hole at $x=-2$).","calc":false,"topic":"","img":[]},{"q":"Where is the hole in the graph of $r(x)=\\dfrac{x^2+x-2}{x^2-1}$?","c":["$\\left(1,\\frac32\\right)$","$(-1,0)$","$(1,0)$","$(-2,0)$"],"a":0,"e":"$\\frac{(x+2)(x-1)}{(x-1)(x+1)}$: hole at $x=1$, height $\\frac32$.","calc":false,"topic":"","img":[]},{"q":"$\\displaystyle\\lim_{x\\to1^+}\\frac{2x}{x-1}$ is","c":["$\\infty$","$-\\infty$","$2$","$0$"],"a":0,"e":"Numerator near $2$, denominator positive and small.","calc":false,"topic":"","img":[]},{"q":"What happens on the graph of $r(x)=\\dfrac{x-2}{(x-2)^2}$ at $x=2$?","c":["a hole","a zero","a vertical asymptote","nothing"],"a":2,"e":"$r(x)=\\frac{1}{x-2}$ for $x\\neq2$.","calc":false,"topic":"","img":[]},{"q":"The graph of $r(x)=\\dfrac{1}{x^2-4}$ is shown. Which statement is true?","c":["$\\lim_{x\\to2^-}r(x)=\\infty$","$\\lim_{x\\to2^+}r(x)=-\\infty$","$\\lim_{x\\to-2^+}r(x)=\\infty$","$\\lim_{x\\to2^-}r(x)=-\\infty$"],"a":3,"e":"Between the asymptotes the graph falls without bound near $x=2$.","calc":false,"topic":"","img":["03d63a72ea65.svg"]},{"q":"The graph of a rational function is a line with a hole at $(2,3)$. Which could be its equation?","c":["$\\dfrac{x^2-4}{x-2}$","$\\dfrac{x+1}{x-2}$","$\\dfrac{x^2-x-2}{x-2}$","$x+1$"],"a":2,"e":"$\\frac{(x-2)(x+1)}{x-2}$.","calc":false,"topic":"","img":["7446683c3d99.svg"]}]},{"id":"pc-u1-1.11","course":"pc","unit":"u1","title":"Topic 1.11 · Rational Functions and Concept of Limit","kind":"quiz","minutes":null,"lesson":"1.11","items":[{"q":"$\\displaystyle\\lim_{x\\to3}\\frac{x^2-3x}{x-3}$ is","c":["$0$","$1$","$9$","$3$"],"a":3,"e":"$\\frac{x(x-3)}{x-3}=x\\to3$.","calc":false,"topic":"","img":[]},{"q":"$\\displaystyle\\lim_{x\\to2}\\frac{x^2-x-2}{x^2-4}$ is","c":["$\\frac34$","$0$","$\\frac12$","It does not exist."],"a":0,"e":"$\\frac{(x-2)(x+1)}{(x-2)(x+2)}\\to\\frac34$.","calc":false,"topic":"","img":[]},{"q":"$\\displaystyle\\lim_{x\\to-1^-}\\frac{x+3}{x+1}$ is","c":["$\\infty$","$-\\infty$","$2$","$1$"],"a":1,"e":"Numerator near $2$; for $x<-1$, $x+1<0$.","calc":false,"topic":"","img":[]},{"q":"Which describes $\\displaystyle\\lim_{x\\to4}\\frac{1}{x-4}$?","c":["$\\infty$","$-\\infty$","$0$","It does not exist (the one-sided limits are $-\\infty$ and $\\infty$)."],"a":3,"e":"Opposite infinite one-sided limits.","calc":false,"topic":"","img":[]},{"q":"What is the remainder when $x^3-2x+5$ is divided by $x-2$?","c":["$1$","$5$","$9$","$13$"],"a":2,"e":"$p(2)=9$.","calc":false,"topic":"","img":[]},{"q":"What is the coefficient of $x^3$ in $(x+2)^5$?","c":["$10$","$20$","$80$","$40$"],"a":3,"e":"$10\\cdot2^2=40$.","calc":false,"topic":"","img":[]},{"q":"Which is the slant asymptote of $r(x)=\\dfrac{2x^2+3x-4}{x+2}$?","c":["$y=2x-1$","$y=2x+7$","$y=2x+3$","$y=x-1$"],"a":0,"e":"Synthetic division gives $2x-1$, remainder $-2$.","calc":false,"topic":"","img":[]}]},{"id":"pc-u1-R1.7-1.11","course":"pc","unit":"u1","title":"Review 1.7-1.11 · Review of Topics 1.7 to 1.11","kind":"quiz","minutes":null,"lesson":"R1.7-1.11","items":[{"q":"Which line is a horizontal asymptote of $r(x)=\\dfrac{3x^2-x}{6x^2+5}$?","c":["$y=3$","$y=0$","$y=-\\frac15$","$y=\\frac12$"],"a":3,"e":"$\\frac36$.","calc":false,"topic":"1.7","img":[]},{"q":"What is $\\displaystyle\\lim_{x\\to2^+}\\frac{x+1}{2-x}$?","c":["$0$","$3$","$\\infty$","$-\\infty$"],"a":3,"e":"Denominator negative near $2^+$.","calc":false,"topic":"1.9","img":[]},{"q":"Let $r(x)=\\dfrac{x^2-1}{x^2+x-2}$. What is true at $x=1$?","c":["vertical asymptote","hole at $\\left(1,\\frac23\\right)$","zero","hole at $(1,0)$"],"a":1,"e":"Cancel $(x-1)$; $\\frac{2}{3}$.","calc":false,"topic":"1.10","img":[]},{"q":"Which value is a zero of $r(x)=\\dfrac{(x+1)(x-5)}{(x-5)(x+3)}$?","c":["$-1$ only","$-1$ and $5$","$5$ only","$-3$"],"a":0,"e":"$5$ is excluded.","calc":false,"topic":"1.8","img":[]},{"q":"The graph of a rational function $s$ has a vertical asymptote $x=2$, horizontal asymptote $y=0$, and passes through $(3,1)$ and $(1,-1)$. Which could be $s(x)$?","c":["$\\frac{1}{x+2}$","$\\frac{1}{x-2}$","$\\frac{x}{x-2}$","$\\frac{x-2}{x}$"],"a":1,"e":"Asymptote $x=2$, $y=0$; $s(3)=1$.","calc":false,"topic":"1.9 \\textbullet\\ graph","img":["9751cad377f4.svg"]},{"q":"$\\displaystyle\\lim_{x\\to-3}\\frac{x^2+x-6}{x^2-9}$ is","c":["$\\frac56$","$0$","$-\\frac56$","It does not exist."],"a":0,"e":"$\\frac{x-2}{x-3}\\to\\frac{-5}{-6}$.","calc":false,"topic":"1.11","img":[]},{"q":"For large positive $x$, $s(x)=\\dfrac{x^2+x-1}{x-1}$ is closest to which line?","c":["$y=x$","$y=x+1$","$y=x+2$","$y=1$"],"a":2,"e":"$s=x+2+\\frac1{x-1}$.","calc":false,"topic":"1.7","img":[]}]},{"id":"pc-u1-1.12","course":"pc","unit":"u1","title":"Topic 1.12 · Transformations of Functions","kind":"quiz","minutes":null,"lesson":"1.12","items":[{"q":"How is the graph of $g(x)=f(x+3)-1$ obtained from the graph of $f$?","c":["right 3, down 1","left 3, down 1","left 3, up 1","right 3, up 1"],"a":1,"e":"","calc":false,"topic":"","img":[]},{"q":"How is the graph of $g(x)=f(2x)$ obtained from the graph of $f$?","c":["vertical dilation by 2","horizontal dilation by 2","horizontal dilation by $\\frac12$","vertical dilation by $\\frac12$"],"a":2,"e":"","calc":false,"topic":"","img":[]},{"q":"How is the graph of $y=-f(x)$ obtained from the graph of $f$?","c":["reflection over the $x$-axis","reflection over the $y$-axis","reflection over $y=x$","shift down 1"],"a":0,"e":"","calc":false,"topic":"","img":[]},{"q":"Which describes $g(x)=3f(-x)$?","c":["reflect over the $x$-axis, vertical dilation by 3","reflect over the $y$-axis, vertical dilation by 3","reflect over the $y$-axis, horizontal dilation by 3","shift left 3"],"a":1,"e":"","calc":false,"topic":"","img":[]},{"q":"The graphs of $f$ (solid) and $g$ (dashed) are shown. Which is $g$ in terms of $f$?","c":["$f(x-2)+1$","$f(x+2)+1$","$f(x-2)-1$","$f(x+2)-1$"],"a":0,"e":"Right 2, up 1.","calc":false,"topic":"","img":["0ec32951aece.svg"]},{"q":"The graphs of $f$ (solid) and $g$ (dashed) are shown. Which is $g$ in terms of $f$?","c":["$-f(x)-1$","$f(-x)+1$","$-f(x)+1$","$-f(x+1)$"],"a":2,"e":"Reflect over the $x$-axis, up 1.","calc":false,"topic":"","img":["6d36d2e4239f.svg"]},{"q":"$f$ has domain $[0,8]$ and range $[-2,3]$. What is the range of $g(x)=-2f\\!\\left(\\frac{x}{2}\\right)+1$?","c":["$[-5,5]$","$[-3,7]$","$[-4,6]$","$[-1,3]$"],"a":0,"e":"$-2\\cdot[-2,3]=[-6,4]$, then $+1$.","calc":false,"topic":"","img":[]},{"q":"For the same $f$, what is the domain of $g$?","c":["$[0,4]$","$[0,16]$","$[-2,6]$","$[0,8]$"],"a":1,"e":"$\\frac x2\\in[0,8]$.","calc":false,"topic":"","img":[]},{"q":"The point $(4,-2)$ is on the graph of $f$. Which point must be on $y=3f(x-1)+2$?","c":["$(3,-4)$","$(5,-6)$","$(5,-4)$","$(4,-4)$"],"a":2,"e":"","calc":false,"topic":"","img":[]},{"q":"$g(x)=f(x-2)+5$. Describe the transformation.","c":["left 2, up 5","right 2, up 5","right 5, up 2","left 5, down 2"],"a":1,"e":"","calc":false,"topic":"","img":[]},{"q":"$g(x)=\\frac13f(x)$. Describe the transformation.","c":["vertical dilation by $\\frac13$","vertical dilation by 3","horizontal dilation by $\\frac13$","horizontal dilation by 3"],"a":0,"e":"","calc":false,"topic":"","img":[]},{"q":"$g(x)=f\\!\\left(\\frac12x\\right)$. Describe the transformation.","c":["horizontal dilation by $\\frac12$","vertical dilation by 2","horizontal dilation by 2","vertical dilation by $\\frac12$"],"a":2,"e":"Factor $\\frac{1}{1/2}=2$.","calc":false,"topic":"","img":[]},{"q":"Which function is the graph of $y=|x|$ reflected over the $x$-axis and shifted right 3?","c":["$-|x+3|$","$|{-x}-3|$","$-|x|+3$","$-|x-3|$"],"a":3,"e":"","calc":false,"topic":"","img":[]},{"q":"The vertex of $y=x^2$ moves to $(-1,4)$ and the graph opens downward with the same shape. Which is the equation?","c":["$y=-(x+1)^2+4$","$y=-(x-1)^2+4$","$y=(x+1)^2-4$","$y=-(x+4)^2-1$"],"a":0,"e":"","calc":false,"topic":"","img":[]},{"q":"$(6,2)$ is on the graph of $f$. Which point is on $y=f(3x)$?","c":["$(18,2)$","$(6,6)$","$(2,2)$","$(2,6)$"],"a":2,"e":"$x=\\frac63=2$.","calc":false,"topic":"","img":[]},{"q":"$f$ has range $[1,5]$. What is the range of $y=-f(x)+2$?","c":["$[-3,1]$","$[3,7]$","$[-5,-1]$","$[1,5]$"],"a":0,"e":"$-f\\in[-5,-1]$, then $+2$.","calc":false,"topic":"","img":[]},{"q":"Which transformation can change the domain of a function?","c":["$f(x)+4$","$3f(x)$","$-f(x)$","$f(x-4)$"],"a":3,"e":"Horizontal changes affect the domain.","calc":false,"topic":"","img":[]},{"q":"The graph of $f$ is shown (solid). The dashed graph is $g$. Which is $g$?","c":["$f(2x)$","$2f(x)$","$f\\!\\left(\\frac12x\\right)$","$\\frac12f(x)$"],"a":2,"e":"Twice as wide, same height: horizontal dilation by 2.","calc":false,"topic":"","img":["5224eda403c8.svg"]},{"q":"Which describes $g(x)=f(-x)$ for an even function $f$?","c":["$g=-f$","$g=f$","$g$ is $f$ shifted left","$g$ is undefined"],"a":1,"e":"Even: $f(-x)=f(x)$.","calc":false,"topic":"","img":[]}]},{"id":"pc-u1-1.13-1.14","course":"pc","unit":"u1","title":"Topic 1.13-1.14 · Function Model Construction","kind":"quiz","minutes":null,"lesson":"1.13-1.14","items":[{"q":"Data with equally spaced inputs have first differences $4.9,\\ 5.1,\\ 5.0,\\ 4.9$. Which model fits best?","c":["linear","quadratic","cubic","rational"],"a":0,"e":"","calc":false,"topic":"","img":[]},{"q":"A company's average cost per item is $A(n)=\\frac{500+4n}{n}$. What does $\\lim_{n\\to\\infty}A(n)$ tell you?","c":["The fixed cost is &#36;500.","The average cost becomes 0.","The average cost per item approaches &#36;4.","The cost per item grows without bound."],"a":2,"e":"","calc":false,"topic":"","img":[]},{"q":"A rectangle has perimeter 40 cm and width $w$. Which gives its area?","c":["$w(40-w)$","$w(20-w)$","$2w+40$","$w^2-20$"],"a":1,"e":"","calc":false,"topic":"","img":[]},{"q":"The height of a model rocket is recorded: $(0,1.2)$, $(1,6.1)$, $(2,9.0)$, $(3,9.9)$, $(4,8.6)$ ($t$ in s, $h$ in m). Using quadratic regression, what is the predicted height at $t=5$?","c":["$4.2$ m","$5.3$ m","$6.4$ m","$7.3$ m"],"a":1,"e":"$h(t)\\approx-1.029t^2+5.974t+1.183$; $h(5)\\approx5.34$.","calc":true,"topic":"","img":[]}]},{"id":"pc-u1-aptest","course":"pc","unit":"u1","title":"Unit 1 AP-style test · multiple choice","kind":"test","minutes":49,"lesson":null,"items":[{"q":"The table gives values of a function $f$ at selected values of $x$. <div class=\"tbl\"><table><tr><td>$x$</td><td>0</td><td>2</td><td>4</td><td>6</td></tr><tr><td>$f(x)$</td><td>5</td><td>9</td><td>11</td><td>12</td></tr></table></div> Which statement is consistent with the table?","c":["$f$ is increasing and its graph is concave up.","$f$ is increasing and its graph is concave down.","$f$ is decreasing and its graph is concave up.","$f$ is decreasing and its graph is concave down."],"a":1,"e":"The outputs increase, so $f$ is increasing. The average rates of change on $[0,2]$, $[2,4]$, $[4,6]$ are $2$, $1$, $0.5$: the rate of change is decreasing, so the graph is concave down.","calc":false,"topic":"1.1","img":[]},{"q":"What is the average rate of change of $f(x)=x^3-2x$ on the interval $[-1,2]$?","c":["$3$","$\\dfrac53$","$1$","$-1$"],"a":2,"e":"$f(2)=8-4=4$ and $f(-1)=-1+2=1$, so $\\dfrac{4-1}{2-(-1)}=\\dfrac33=1$.","calc":false,"topic":"1.2","img":[]},{"q":"<div class=\"tbl\"><table><tr><td>$x$</td><td>1</td><td>2</td><td>3</td><td>4</td><td>5</td></tr><tr><td>$y$</td><td>2</td><td>5</td><td>10</td><td>17</td><td>26</td></tr></table></div> Which type of function best models the data in the table?","c":["Quadratic","Linear","Cubic","Constant"],"a":0,"e":"The first differences are $3, 5, 7, 9$ and the second differences are all $2$. Constant second differences over equal input intervals indicate a quadratic model ($y=x^2+1$).","calc":false,"topic":"1.3","img":[]},{"q":"A polynomial $p$ of degree 4 has real coefficients. Two of its zeros are $2$ and $1+3i$. Which of the following must also be a zero of $p$?","c":["$-2$","$3+i$","$-1-3i$","$1-3i$"],"a":3,"e":"Non-real zeros of a polynomial with real coefficients come in conjugate pairs, so $1-3i$ is a zero.","calc":false,"topic":"1.5","img":[]},{"q":"Let $p(x)=x^2(x-3)^3(x+1)$. What is $\\displaystyle\\lim_{x\\to-\\infty}p(x)$?","c":["$-\\infty$","$+\\infty$","$0$","$1$"],"a":1,"e":"The leading term is $x^2\\cdot x^3\\cdot x=x^6$: even degree with positive leading coefficient, so $p(x)\\to+\\infty$ as $x\\to-\\infty$.","calc":false,"topic":"1.6","img":[]},{"q":"Which statement describes the graph of $p(x)=(x+2)^2(x-1)$ at $x=-2$?","c":["It has a vertical asymptote.","It crosses the $x$-axis.","It touches the $x$-axis without crossing it.","It has a hole."],"a":2,"e":"$x=-2$ is a zero of even multiplicity (2), so the graph touches the $x$-axis and turns back. Polynomials have no asymptotes or holes.","calc":false,"topic":"1.5","img":[]},{"q":"Which line is a horizontal asymptote of the graph of $r(x)=\\dfrac{3x^2-x}{6x^2+5}$?","c":["$y=3$","$y=0$","$y=-\\dfrac15$","$y=\\dfrac12$"],"a":3,"e":"The degrees are equal, so the asymptote is the ratio of leading coefficients: $y=\\frac36=\\frac12$.","calc":false,"topic":"1.7","img":[]},{"q":"Let $r(x)=\\dfrac{x^2-1}{x^2+x-2}$. Which statement is true about the graph of $r$ at $x=1$?","c":["It has a vertical asymptote $x=1$.","It has a hole at $\\left(1,\\frac23\\right)$.","It has a zero at $x=1$.","It has a hole at $(1,0)$."],"a":1,"e":"$r(x)=\\dfrac{(x-1)(x+1)}{(x-1)(x+2)}$. The factor $(x-1)$ cancels, so there is a hole at $x=1$. Its height is $\\dfrac{1+1}{1+2}=\\dfrac23$.","calc":false,"topic":"1.10","img":[]},{"q":"What is $\\displaystyle\\lim_{x\\to2^+}\\frac{x+1}{2-x}$?","c":["$0$","$3$","$+\\infty$","$-\\infty$"],"a":3,"e":"As $x\\to2^+$, the numerator approaches $3>0$ and the denominator $2-x$ approaches $0$ through negative values. The quotient decreases without bound.","calc":false,"topic":"1.9","img":[]},{"q":"The graph of $r(x)=\\dfrac{2x^2+3x-4}{x+2}$ has a slant asymptote. What is its equation?","c":["$y=2x-1$","$y=2x+7$","$y=2x+3$","$y=x-1$"],"a":0,"e":"Synthetic division by $-2$ on $2,\\ 3,\\ -4$ gives $2,\\ -1$ with remainder $-2$, so $r(x)=2x-1-\\dfrac{2}{x+2}$. As $x\\to\\pm\\infty$ the fraction goes to $0$.","calc":false,"topic":"1.11","img":[]},{"q":"What is the coefficient of $x^2$ in the expansion of $(x-3)^4$?","c":["$6$","$-108$","$54$","$9$"],"a":2,"e":"Row 4 of Pascal's triangle is $1,4,6,4,1$. The $x^2$ term is $6\\,x^2(-3)^2=54x^2$.","calc":false,"topic":"1.11","img":[]},{"q":"The function $f$ has domain $[0,8]$ and range $[-2,3]$. What is the range of $g(x)=-2f\\!\\left(\\frac{x}{2}\\right)+1$?","c":["$[-5,5]$","$[-3,7]$","$[-4,6]$","$[-1,3]$"],"a":0,"e":"The horizontal dilation does not change the range. Multiplying $[-2,3]$ by $-2$ gives $[-6,4]$; adding 1 gives $[-5,5]$.","calc":false,"topic":"1.12","img":[]},{"q":"Which function is even?","c":["$f(x)=x^3-x$","$f(x)=x^4+3x^2-1$","$f(x)=x^2+x$","$f(x)=(x-1)^2$"],"a":1,"e":"$(-x)^4+3(-x)^2-1=x^4+3x^2-1$, so $f(-x)=f(x)$. The others fail this test (for example, (C) gives $x^2-x$).","calc":false,"topic":"1.5","img":[]},{"q":"What is the solution set of $\\dfrac{x-3}{x+1}\\ge0$?","c":["$(-\\infty,-1]\\cup[3,\\infty)$","$[3,\\infty)$","$(-1,3]$","$(-\\infty,-1)\\cup[3,\\infty)$"],"a":3,"e":"The sign can change only at the zero $x=3$ and at $x=-1$ (excluded). Test points: $x=-2$ gives $\\frac{-5}{-1}>0$, $x=0$ gives $-3<0$, $x=4$ gives $\\frac15>0$. Include $x=3$ (value 0) but not $x=-1$.","calc":false,"topic":"1.8","img":[]},{"q":"Which of the following could be an expression for $p(x)$?","c":["$x(x-3)^2$","$-x^2(x-3)$","$x^2(x-3)$","$x^2(x+3)$"],"a":2,"e":"The graph touches the $x$-axis at $x=0$ (even multiplicity) and crosses at $x=3$ (odd multiplicity), and it rises to the right, so the leading coefficient is positive. Check: $p(2)=4(-1)=-4$ matches the graph.","calc":false,"topic":"1.5 \\textbullet\\ graph","img":["b79ca31782b3.svg"]},{"q":"On which interval is $p$ decreasing?","c":["$(-\\infty,0)$","$(0,2)$","$(2,\\infty)$","$(0,3)$"],"a":1,"e":"The graph falls from the local maximum $(0,0)$ to the local minimum $(2,-4)$ and rises elsewhere.","calc":false,"topic":"1.4 \\textbullet\\ graph","img":["b79ca31782b3.svg"]},{"q":"What is the average rate of change of $p$ on the interval $[1,3]$?","c":["$-2$","$0$","$2$","$1$"],"a":3,"e":"From the graph, $p(1)=-2$ and $p(3)=0$, so $\\dfrac{0-(-2)}{3-1}=1$.","calc":false,"topic":"1.2 \\textbullet\\ graph","img":["b79ca31782b3.svg"]},{"q":"The graph of $p$ has a point of inflection at $(1,-2)$. On which interval is the graph of $p$ concave up?","c":["$(1,\\infty)$","$(-\\infty,1)$","$(0,2)$","$(-\\infty,0)$"],"a":0,"e":"Left of $x=1$ the rate of change decreases (the graph bends downward); right of $x=1$ it increases, so the graph is concave up on $(1,\\infty)$.","calc":false,"topic":"1.4 \\textbullet\\ graph","img":["b79ca31782b3.svg"]},{"q":"The graph of a rational function $s$ is shown. It has a vertical asymptote $x=2$ and a horizontal asymptote $y=0$, and it passes through $(3,1)$ and $(1,-1)$. Which could be an expression for $s(x)$?","c":["$\\dfrac{1}{x+2}$","$\\dfrac{1}{x-2}$","$\\dfrac{x}{x-2}$","$\\dfrac{x-2}{x}$"],"a":1,"e":"A vertical asymptote at $x=2$ needs the factor $x-2$ in the denominator only. $y=0$ as horizontal asymptote rules out (C) and (D) (their asymptote is $y=1$). Check: $\\frac{1}{3-2}=1$ and $\\frac{1}{1-2}=-1$.","calc":false,"topic":"1.9 \\textbullet\\ graph","img":["5e98135f22d8.svg"]},{"q":"The graphs of $f$ (solid) and $g$ (dashed) are shown. Which is an equation for $g$ in terms of $f$?","c":["$g(x)=f(x-2)+1$","$g(x)=f(x+2)+1$","$g(x)=f(x-2)-1$","$g(x)=f(x+2)-1$"],"a":0,"e":"Each point of $f$ moves 2 units right and 1 unit up: $(-3,0)\\to(-1,1)$, $(-1,2)\\to(1,3)$, $(1,-1)\\to(3,0)$. That is $g(x)=f(x-2)+1$.","calc":false,"topic":"1.12 \\textbullet\\ graph","img":["da1f21e2c32d.svg"]},{"q":"An open box is made from a $16$ in by $10$ in sheet by cutting squares of side $x$ in from the corners. Its volume is $V(x)=x(16-2x)(10-2x)$ for $0<x<5$. What is the maximum volume of the box?","c":["$120$ in$^3$","$144$ in$^3$","$160$ in$^3$","$168$ in$^3$"],"a":1,"e":"Graph $V$ on $0<x<5$ and use the maximum feature: the maximum occurs at $x=2$, with $V(2)=2\\cdot12\\cdot6=144$ in$^3$.","calc":true,"topic":"1.14","img":[]},{"q":"The height $h$, in meters, of a model rocket was measured at times $t$, in seconds. <div class=\"tbl\"><table><tr><td>$t$</td><td>0</td><td>1</td><td>2</td><td>3</td><td>4</td></tr><tr><td>$h(t)$</td><td>1.2</td><td>6.1</td><td>9.0</td><td>9.9</td><td>8.6</td></tr></table></div> Using a quadratic regression, what is the predicted height at $t=5$ seconds?","c":["$4.2$ m","$5.3$ m","$6.4$ m","$7.3$ m"],"a":1,"e":"The quadratic regression is $h(t)\\approx-1.029t^2+5.974t+1.183$, so $h(5)\\approx5.34$ m.","calc":true,"topic":"1.14","img":[]}]},{"id":"ab-u1-SC1.1","course":"ab","unit":"u1","title":"Self Check 1.1 · Lessons 1-1 and 1-2","kind":"quiz","minutes":null,"lesson":null,"items":[{"q":"Using the graph of $f$, $\\displaystyle\\lim_{x\\to-1^+}f(x)=$","c":["$3$","$1$","$0$","It does not exist."],"a":1,"e":"","calc":false,"topic":"","img":["a88d1042da2f.svg"]},{"q":"Using the graph of $f$, $\\displaystyle\\lim_{x\\to3}f(x)=$","c":["$1$","$3$","$2$","$4$"],"a":2,"e":"$8-6=2$.","calc":false,"topic":"","img":["a88d1042da2f.svg"]},{"q":"$\\displaystyle\\lim_{x\\to-2}\\frac{x^2-4}{x+2}=$","c":["$0$","$-4$","$4$","It does not exist."],"a":1,"e":"","calc":false,"topic":"","img":[]},{"q":"$\\displaystyle\\lim_{x\\to4}\\frac{\\sqrt x-2}{x-4}=$","c":["$\\frac14$","$\\frac12$","$0$","$4$"],"a":0,"e":"","calc":false,"topic":"","img":[]}]},{"id":"ab-u1-SC1.2","course":"ab","unit":"u1","title":"Self Check 1.2 · Lessons 1-3 and 1-4","kind":"quiz","minutes":null,"lesson":null,"items":[{"q":"$\\displaystyle\\lim_{x\\to\\infty}\\frac{3x^2+1}{x^2-5}=$","c":["$3$","$-\\frac15$","$0$","$\\infty$"],"a":0,"e":"","calc":false,"topic":"","img":[]},{"q":"$\\displaystyle\\lim_{x\\to2}\\frac{3}{(x-2)^2}=$","c":["$\\infty$","$-\\infty$","$3$","It does not exist and is not infinite."],"a":0,"e":"","calc":false,"topic":"","img":[]},{"q":"For what $a$ is $f(x)=\\begin{cases}ax+2, & x<3<br> x^2-a, & x\\ge3\\end{cases}$ continuous?","c":["$\\frac{11}4$","$\\frac74$","$\\frac72$","$7$"],"a":1,"e":"$3a+2=9-a$.","calc":false,"topic":"","img":[]},{"q":"Which condition for continuity fails for $f(x)=\\frac{x^2-9}{x-3}$ at $x=3$?","c":["$f(3)$ is defined","the limit exists","the limit equals $f(3)$","none"],"a":0,"e":"$f(3)$ is undefined.","calc":false,"topic":"","img":[]}]},{"id":"ab-u1-SC1.1-1.2","course":"ab","unit":"u1","title":"Self Check 1.1 and 1.2 · Lessons 1-1 to 1-4","kind":"quiz","minutes":null,"lesson":null,"items":[{"q":"$\\displaystyle\\lim_{x\\to-3}\\frac{x^2+x-6}{x^2-9}=$","c":["$\\frac56$","$0$","$-\\frac56$","It does not exist."],"a":0,"e":"","calc":false,"topic":"","img":[]},{"q":"$\\displaystyle\\lim_{x\\to\\infty}\\frac{x^2}{e^x}=$","c":["$\\infty$","$1$","$e$","$0$"],"a":3,"e":"","calc":false,"topic":"","img":[]},{"q":"$\\displaystyle\\lim_{x\\to-1}\\frac{x^2-1}{|x+1|}$","c":["$2$","$-2$","$0$","does not exist"],"a":3,"e":"Left $2$, right $-2$.","calc":false,"topic":"","img":[]},{"q":"Using the graph of $g$, at which $x$ is the discontinuity removable?","c":["$x=-1$","$x=3$","$x=-4$","$x=1$"],"a":3,"e":"","calc":false,"topic":"","img":["5c7ede26b25c.svg"]}]},{"id":"ab-u1-SC1.3","course":"ab","unit":"u1","title":"Self Check 1.3 · Lessons 1-5 and 1-6","kind":"quiz","minutes":null,"lesson":null,"items":[{"q":"$f$ is continuous, $f(0)=3$, $f(4)=-1$. Which must be true?","c":["$f(2)=1$","$f(c)=0$ for some $c$ in $(0,4)$","exactly one zero","$f(c)=4$"],"a":1,"e":"","calc":false,"topic":"","img":[]},{"q":"Why does $\\frac1x$ on $[-1,1]$ never equal $0$, although $f(-1)<0<f(1)$?","c":["$0$ is not between them","IVT is only for polynomials","not continuous on $[-1,1]$","it is decreasing"],"a":2,"e":"","calc":false,"topic":"","img":[]},{"q":"What is the average rate of change of $h(x)=\\frac{12}{x}$ on $[2,6]$?","c":["$-1$","$-4$","$1$","$-\\frac12$"],"a":0,"e":"","calc":false,"topic":"","img":[]}]},{"id":"ab-u1-SC1.4","course":"ab","unit":"u1","title":"Self Check 1.4 · Lessons 1-7 to 1-9","kind":"quiz","minutes":null,"lesson":null,"items":[{"q":"$\\displaystyle\\lim_{h\\to0}\\frac{\\frac1{2+h}-\\frac12}{h}$ equals $k'(2)$ for $k(x)=\\frac1x$. Its value is","c":["$\\frac12$","$-\\frac14$","$-\\frac12$","$\\frac14$"],"a":1,"e":"","calc":false,"topic":"","img":[]},{"q":"Where is $f(x)=\\sqrt[3]{x}$ continuous but not differentiable?","c":["$x=1$","$x=0$","$x=-1$","nowhere"],"a":1,"e":"Vertical tangent.","calc":false,"topic":"","img":[]},{"q":"For $k(x)=\\frac1x$ on $[1,4]$, the MVT gives $c=$","c":["$2.5$","$\\sqrt{2}$","$2$","$3$"],"a":2,"e":"","calc":false,"topic":"","img":[]}]},{"id":"ab-u1-SC1.3-1.4","course":"ab","unit":"u1","title":"Self Check 1.3 and 1.4 · Lessons 1-5 to 1-9","kind":"quiz","minutes":null,"lesson":null,"items":[{"q":"Which function must have an absolute minimum on the interval?","c":["$\\frac1x$ on $[1,3]$","$\\frac1x$ on $(0,3]$","$x$ on $(0,1)$","$\\ln x$ on $(0,1]$"],"a":0,"e":"","calc":false,"topic":"","img":[]},{"q":"For $f(x)=x^2$, $\\frac{f(1+h)-f(1)}{h}=$","c":["$2$","$2+h$","$1+h$","$h$"],"a":1,"e":"","calc":false,"topic":"","img":[]},{"q":"For $g(x)=x^3$ on $[0,3]$, the MVT value is $c=$","c":["$1.5$","$3$","$\\sqrt3$","$\\sqrt[3]9$"],"a":2,"e":"","calc":false,"topic":"","img":[]}]},{"id":"ab-u1-PRETEST1","course":"ab","unit":"u1","title":"Unit 1 Pretest · Limits, Continuity, and Differentiability","kind":"test","minutes":25,"lesson":null,"items":[{"q":"$\\displaystyle\\lim_{x\\to3}\\frac{x^2-9}{x-3}$ is","c":["$0$","$3$","$6$","nonexistent"],"a":2,"e":"","calc":false,"topic":"","img":[]},{"q":"$\\displaystyle\\lim_{x\\to\\infty}\\frac{5x^2-x}{2x^2+3}$ is","c":["$0$","$\\frac52$","$5$","$\\infty$"],"a":1,"e":"","calc":false,"topic":"","img":[]},{"q":"$\\displaystyle\\lim_{x\\to1^-}\\frac{2}{x-1}$ is","c":["$\\infty$","$2$","$0$","$-\\infty$"],"a":3,"e":"","calc":false,"topic":"","img":[]},{"q":"$\\displaystyle\\lim_{x\\to0}\\frac{\\sin3x}{x}$ is","c":["$0$","$1$","$3$","$\\frac13$"],"a":2,"e":"","calc":false,"topic":"","img":[]},{"q":"Using the graph of $f$, which limit does not exist?","c":["$\\lim_{x\\to0}f(x)$","$\\lim_{x\\to-1}f(x)$","$\\lim_{x\\to2}f(x)$","$\\lim_{x\\to3}f(x)$"],"a":1,"e":"","calc":false,"topic":"","img":["a88d1042da2f.svg"]},{"q":"Using the graph of $f$, at which $x$ is the discontinuity removable?","c":["$x=-1$","$x=0$","$x=2$","$x=3$"],"a":2,"e":"","calc":false,"topic":"","img":["a88d1042da2f.svg"]},{"q":"For which $k$ is $f(x)=\\begin{cases}kx^2, & x\\le1<br> x+3, & x>1\\end{cases}$ continuous?","c":["$4$","$3$","$1$","$2$"],"a":0,"e":"","calc":false,"topic":"","img":[]},{"q":"$f$ is continuous on $[2,6]$, $f(2)=5$, $f(6)=-3$. Which must be true?","c":["$f(4)=1$","$f(c)=0$ for some $c$","$f$ has no maximum","$f'(c)=-2$"],"a":1,"e":"IVT. (D) needs differentiability.","calc":false,"topic":"","img":[]},{"q":"Which describes $\\displaystyle\\lim_{h\\to0}\\frac{(2+h)^3-8}{h}$?","c":["$f'(2)$ for $f(x)=x^3$, equal to $12$","$f'(8)$, equal to $3$","$0$","$8$"],"a":0,"e":"","calc":false,"topic":"","img":[]},{"q":"$f(x)=|x+1|$ is not differentiable at","c":["$x=1$","$x=0$","$x=-1$","nowhere"],"a":2,"e":"","calc":false,"topic":"","img":[]}]},{"id":"ab-u1-FIXUP1","course":"ab","unit":"u1","title":"Unit 1 Fix-Up · Limits, Continuity, and Differentiability","kind":"test","minutes":25,"lesson":null,"items":[{"q":"$\\displaystyle\\lim_{x\\to-4}\\frac{x^2-16}{x+4}$ is","c":["$0$","$-8$","$8$","nonexistent"],"a":1,"e":"","calc":false,"topic":"","img":[]},{"q":"$\\displaystyle\\lim_{x\\to\\infty}\\frac{2x-7}{x^2+1}$ is","c":["$0$","$2$","$-7$","$\\infty$"],"a":0,"e":"","calc":false,"topic":"","img":[]},{"q":"$\\displaystyle\\lim_{x\\to3^+}\\frac{-1}{x-3}$ is","c":["$\\infty$","$-1$","$-\\infty$","$0$"],"a":2,"e":"","calc":false,"topic":"","img":[]},{"q":"$\\displaystyle\\lim_{x\\to0}\\frac{\\sin x}{4x}$ is","c":["$4$","$\\frac14$","$1$","$0$"],"a":1,"e":"","calc":false,"topic":"","img":[]},{"q":"Using the graph of $g$, which limit does not exist?","c":["$\\lim_{x\\to1}g(x)$","$\\lim_{x\\to4}g(x)$","$\\lim_{x\\to-1}g(x)$","$\\lim_{x\\to-2}g(x)$"],"a":2,"e":"","calc":false,"topic":"","img":["5c7ede26b25c.svg"]},{"q":"Using the graph of $g$, what type of discontinuity is at $x=3$?","c":["removable","jump","infinite","none"],"a":2,"e":"","calc":false,"topic":"","img":["5c7ede26b25c.svg"]},{"q":"For which $k$ is $f(x)=\\begin{cases}2x+k, & x<1<br> kx^2+3, & x\\ge1\\end{cases}$ continuous?","c":["$1$","$-1$","It is continuous for every $k$.","No value of $k$ works."],"a":3,"e":"$2+k=k+3$ is impossible.","calc":false,"topic":"","img":[]},{"q":"Which function must have an absolute maximum on $[0,2]$?","c":["$\\frac{1}{x-1}$","$\\frac{1}{x+1}$","$\\tan(x)$ with $x$ in radians","$\\frac{1}{x}$"],"a":1,"e":"Continuous on $[0,2]$. ($\\tan$ is undefined at $\\frac\\pi2\\approx1.57$.)","calc":false,"topic":"","img":[]},{"q":"$\\displaystyle\\lim_{x\\to5}\\frac{x^2-25}{x-5}$ represents $f'(5)$ for which $f$?","c":["$f(x)=x^2$","$f(x)=x-5$","$f(x)=x^2-25$ at $x=0$","$f(x)=2x$"],"a":0,"e":"$\\frac{f(x)-f(5)}{x-5}$ with $f(5)=25$; value $10$.","calc":false,"topic":"","img":[]},{"q":"For $f(x)=x^2$ on $[2,6]$, the MVT gives $c=$","c":["$3$","$5$","$4$","$8$"],"a":2,"e":"Secant slope $\\frac{36-4}{4}=8=2c$.","calc":false,"topic":"","img":[]}]},{"id":"ab-u1-1-1","course":"ab","unit":"u1","title":"Lesson 1-1 · Limits to a Point on a Graph","kind":"quiz","minutes":null,"lesson":"1-1","items":[{"q":"What is $\\displaystyle\\lim_{x\\to-1^-}f(x)$?","c":["$3$","$1$","$2$","It does not exist."],"a":0,"e":"From the left the segment approaches the open circle at height $3$.","calc":false,"topic":"","img":["a88d1042da2f.svg"]},{"q":"What is $\\displaystyle\\lim_{x\\to2}f(x)$?","c":["$1$","$2$","$4$","It does not exist."],"a":2,"e":"Both pieces approach $(2,4)$.","calc":false,"topic":"","img":["a88d1042da2f.svg"]},{"q":"For which value of $x$ in $(-3,4)$ does $\\lim f(x)$ fail to exist?","c":["$x=2$","$x=0$","$x=3$","$x=-1$"],"a":3,"e":"One-sided limits $3$ and $1$.","calc":false,"topic":"","img":["a88d1042da2f.svg"]},{"q":"What is $\\displaystyle\\lim_{x\\to1}\\big(f(x)+2x\\big)$?","c":["$1$","$3$","$2$","$4$"],"a":1,"e":"$1+2=3$.","calc":false,"topic":"","img":["a88d1042da2f.svg"]},{"q":"Which statement is true?","c":["$\\lim_{x\\to2}f(x)=f(2)$","$\\lim_{x\\to-1^+}f(x)=f(-1)$","$\\lim_{x\\to-1}f(x)=1$","$f(2)=4$"],"a":1,"e":"$\\lim_{x\\to-1^+}f(x)=1=f(-1)$. The limit at $2$ is $4$ but $f(2)=1$.","calc":false,"topic":"","img":["a88d1042da2f.svg"]}]},{"id":"ab-u1-1-2","course":"ab","unit":"u1","title":"Lesson 1-2 · Limits to a Point of a Function","kind":"quiz","minutes":null,"lesson":"1-2","items":[{"q":"$\\displaystyle\\lim_{x\\to3}\\frac{x^2-9}{x^2-2x-3}$ is","c":["$0$","$\\frac32$","$3$","nonexistent"],"a":1,"e":"$\\frac{x+3}{x+1}\\to\\frac64$.","calc":false,"topic":"","img":[]},{"q":"$\\displaystyle\\lim_{x\\to0}\\frac{\\sqrt{x+9}-3}{x}$ is","c":["$0$","$\\frac13$","$\\frac16$","$3$"],"a":2,"e":"Conjugate: $\\frac{1}{\\sqrt{x+9}+3}$.","calc":false,"topic":"","img":[]},{"q":"$\\displaystyle\\lim_{x\\to0}\\frac{\\sin(5x)}{x}$ is","c":["$5$","$1$","$\\frac15$","$0$"],"a":0,"e":"","calc":false,"topic":"","img":[]},{"q":"$\\displaystyle\\lim_{x\\to2^-}\\frac{|x-2|}{x-2}$ is","c":["$1$","$0$","$-1$","nonexistent"],"a":2,"e":"","calc":false,"topic":"","img":[]},{"q":"$\\displaystyle\\lim_{x\\to4}\\frac{x+1}{(x-4)^2}$ is","c":["$0$","$-\\infty$","$\\frac54$","$\\infty$"],"a":3,"e":"$\\frac50$ with a positive denominator on both sides.","calc":false,"topic":"","img":[]},{"q":"$\\displaystyle\\lim_{x\\to0}x^2\\cos\\frac1x$ is","c":["$1$","$0$","$-1$","nonexistent"],"a":1,"e":"Squeeze between $\\pm x^2$.","calc":false,"topic":"","img":[]}]},{"id":"ab-u1-1-3","course":"ab","unit":"u1","title":"Lesson 1-3 · Limits to Infinity and Horizontal Asymptotes","kind":"quiz","minutes":null,"lesson":"1-3","items":[{"q":"$\\displaystyle\\lim_{x\\to\\infty}\\frac{4x^3-x}{2x^3+7x^2}$ is","c":["$0$","$\\frac47$","$\\infty$","$2$"],"a":3,"e":"","calc":false,"topic":"","img":[]},{"q":"$\\displaystyle\\lim_{x\\to-\\infty}\\frac{2x}{\\sqrt{x^2+5}}$ is","c":["$2$","$-2$","$0$","$-\\infty$"],"a":1,"e":"$\\sqrt{x^2}=-x$ for $x<0$.","calc":false,"topic":"","img":[]},{"q":"$\\displaystyle\\lim_{x\\to\\infty}\\frac{3e^x+x^2}{e^x-1}$ is","c":["$0$","$1$","$3$","$\\infty$"],"a":2,"e":"","calc":false,"topic":"","img":[]},{"q":"Which line or lines are vertical asymptotes of $h(x)=\\dfrac{x+1}{x^2-1}$?","c":["$x=1$ only","$x=-1$ only","$x=1$ and $x=-1$","$y=0$ only"],"a":0,"e":"Hole at $x=-1$.","calc":false,"topic":"","img":[]},{"q":"The graph of $f(x)=\\frac{2x}{\\sqrt{x^2+1}}$ is shown. Which are its horizontal asymptotes?","c":["$y=2$ only","$y=0$","$y=2$ and $y=-2$","$x=2$ and $x=-2$"],"a":2,"e":"","calc":false,"topic":"","img":["4764dbd427c1.svg"]}]},{"id":"ab-u1-1-4","course":"ab","unit":"u1","title":"Lesson 1-4 · Continuity at a Point","kind":"quiz","minutes":null,"lesson":"1-4","items":[{"q":"Let $f(x)=\\begin{cases}x^2+1, & x<1<br> 3x-1, & x\\ge1.\\end{cases}$ Which is true?","c":["$\\lim_{x\\to1}f(x)$ does not exist.","The limit exists but $f$ is not continuous at $x=1$.","$f$ is continuous at $x=1$.","$f(1)$ is undefined."],"a":2,"e":"Limits $2$ and $2$, $f(1)=2$.","calc":false,"topic":"","img":[]},{"q":"For what value of $k$ is $f(x)=\\begin{cases}kx+3, & x\\le2<br> x^2-k, & x>2\\end{cases}$ continuous?","c":["$-\\frac13$","$\\frac13$","$1$","$7$"],"a":1,"e":"$2k+3=4-k$.","calc":false,"topic":"","img":[]},{"q":"What type of discontinuity does $g(x)=\\dfrac{x^2-4}{x-2}$ have at $x=2$?","c":["jump","infinite","removable","none"],"a":2,"e":"","calc":false,"topic":"","img":[]},{"q":"The graph of $f$ is shown. Which statement is true?","c":["continuous at $x=3$ but not at $x=1$","continuous at $x=1$ but not at $x=3$","continuous at both","continuous at neither"],"a":1,"e":"","calc":false,"topic":"","img":["ed9e07de590f.svg"]},{"q":"On which interval is $h(x)=\\dfrac{\\sqrt{x+2}}{x-1}$ continuous?","c":["$(-2,\\infty)$","$[-2,1)\\cup(1,\\infty)$","$(1,\\infty)$","all real numbers except $1$"],"a":1,"e":"","calc":false,"topic":"","img":[]}]},{"id":"ab-u1-1-5","course":"ab","unit":"u1","title":"Lesson 1-5 · IVT and EVT","kind":"quiz","minutes":null,"lesson":"1-5","items":[{"q":"$f$ is continuous on $[1,5]$ with $f(1)=-2$ and $f(5)=6$. Which must be true?","c":["$f(c)=8$ for some $c$","$f(3)=2$","$f$ is increasing","$f(c)=4$ for some $c$ in $(1,5)$"],"a":3,"e":"IVT.","calc":false,"topic":"","img":[]},{"q":"Which function is guaranteed to have an absolute maximum on the given interval?","c":["$\\frac1x$ on $(0,1]$","$x^2$ on $(-1,2)$","$\\sqrt{x}$ on $[0,4]$","$\\tan x$ on $\\left[0,\\frac\\pi2\\right)$"],"a":2,"e":"Continuous on a closed interval (EVT).","calc":false,"topic":"","img":[]},{"q":"$g$ is continuous with $g(0)=2$, $g(1)=-1$, $g(2)=1$, $g(3)=4$. What is the least number of zeros of $g$ on $[0,3]$?","c":["$0$","$1$","$3$","$2$"],"a":3,"e":"","calc":false,"topic":"","img":[]},{"q":"The graph of $f(x)=(x-1)(x-2)(x-3)+1$ on $[0,4]$ is shown with the line $y=1$. How many values of $c$ in $[0,4]$ satisfy $f(c)=1$?","c":["exactly one","exactly two","three","none"],"a":2,"e":"$c=1,2,3$; the IVT only guarantees one.","calc":false,"topic":"","img":["c725d78b7ddd.svg"]}]},{"id":"ab-u1-1-6","course":"ab","unit":"u1","title":"Lesson 1-6 · Average Rate of Change","kind":"quiz","minutes":null,"lesson":"1-6","items":[{"q":"What is the average rate of change of $f(x)=x^3-2x$ on $[-1,2]$?","c":["$3$","$\\frac53$","$1$","$-1$"],"a":2,"e":"","calc":false,"topic":"","img":[]},{"q":"For $f(x)=x^2+x$, which is $\\dfrac{f(2+h)-f(2)}{h}$ for $h\\neq0$?","c":["$5$","$5+h$","$4+h$","$h^2+5h$"],"a":1,"e":"$\\frac{(2+h)^2+(2+h)-6}{h}=\\frac{5h+h^2}{h}$.","calc":false,"topic":"","img":[]},{"q":"The position (m) of a particle is graphed. What is its average velocity on $[2,6]$?","c":["$-1$ m/s","$-2$ m/s","$1$ m/s","$0$ m/s"],"a":0,"e":"$\\frac{2-6}{4}=-1$.","calc":false,"topic":"","img":["4a4bc2596f19.svg"]},{"q":"$V(t)$ is a volume in liters, $t$ in minutes. Units of $\\frac{V(8)-V(2)}{6}$?","c":["liters","minutes per liter","liters per minute","liters per minute per minute"],"a":2,"e":"","calc":false,"topic":"","img":[]}]},{"id":"ab-u1-1-7","course":"ab","unit":"u1","title":"Lesson 1-7 · Instantaneous Rates of Change","kind":"quiz","minutes":null,"lesson":"1-7","items":[{"q":"$\\displaystyle\\lim_{h\\to0}\\frac{(3+h)^2-9}{h}$ is","c":["$9$","$0$","$6$","$3$"],"a":2,"e":"It is $f'(3)$ for $f(x)=x^2$.","calc":false,"topic":"","img":[]},{"q":"$\\displaystyle\\lim_{h\\to0}\\frac{\\sqrt{4+h}-2}{h}$ represents $f'(a)$ for which $f$ and $a$?","c":["$f(x)=\\sqrt x$, $a=4$","$f(x)=\\sqrt x$, $a=2$","$f(x)=\\sqrt{x+4}$, $a=2$","$f(x)=x^2$, $a=4$"],"a":0,"e":"","calc":false,"topic":"","img":[]},{"q":"Using $g'(x)=3x^2$ for $g(x)=x^3$, which is the tangent line to $y=x^3$ at $x=1$?","c":["$y=3x-2$","$y=3x+1$","$y=x$","$y=3x$"],"a":0,"e":"Point $(1,1)$, slope $3$: $y-1=3(x-1)$.","calc":false,"topic":"","img":[]},{"q":"At which point is $f(x)=|x-2|+1$ continuous but not differentiable?","c":["$x=1$","$x=2$","$x=-2$","nowhere"],"a":1,"e":"Corner.","calc":false,"topic":"","img":[]},{"q":"$s$ is differentiable; $s(2)=9$, $s(4)=20$, $s(6)=35$. Which is the best estimate of $s'(4)$?","c":["$5.5$","$6.5$","$7.5$","$20$"],"a":1,"e":"$\\frac{35-9}{4}$.","calc":false,"topic":"","img":[]}]},{"id":"ab-u1-1-8","course":"ab","unit":"u1","title":"Lesson 1-8 · MVT","kind":"quiz","minutes":null,"lesson":"1-8","items":[{"q":"For $f(x)=x^2$ on $[0,4]$, which value of $c$ satisfies the MVT?","c":["$1$","$2$","$3$","$4$"],"a":1,"e":"Secant slope $4=2c$.","calc":false,"topic":"","img":[]},{"q":"For which function does the MVT apply on $[-1,1]$?","c":["$|x|$","$\\frac1x$","$x^3$","$\\sqrt[3]{x}$"],"a":2,"e":"$|x|$ has a corner and $\\sqrt[3]x$ a vertical tangent at $0$; $\\frac1x$ is discontinuous.","calc":false,"topic":"","img":[]},{"q":"$f$ is differentiable, $f(1)=4$ and $f(5)=-4$. Which must be true?","c":["$f'(c)=-2$ for some $c$ in $(1,5)$","$f'(3)=-2$","$f(c)=0$ only once","$f'(c)=0$ for some $c$"],"a":0,"e":"$\\frac{-8}{4}=-2$.","calc":false,"topic":"","img":[]}]},{"id":"ab-u1-1-9","course":"ab","unit":"u1","title":"Lesson 1-9 · IVT, EVT, and MVT","kind":"quiz","minutes":null,"lesson":"1-9","items":[{"q":"``Was there a time when the water level was exactly 3 m?'' Which theorem answers this?","c":["IVT","EVT","MVT","none"],"a":0,"e":"","calc":false,"topic":"","img":[]},{"q":"``Was the water level ever rising at exactly 0.5 m per hour?'' Which theorem answers this?","c":["IVT","EVT","MVT","none"],"a":2,"e":"","calc":false,"topic":"","img":[]},{"q":"The graph of $f$ on $[0,4]$ has a corner at $x=2$ and no breaks. Which theorems are guaranteed to apply on $[0,4]$?","c":["IVT only","IVT and EVT","EVT and MVT","IVT, EVT and MVT"],"a":1,"e":"Not differentiable at $x=2$.","calc":false,"topic":"","img":[]}]},{"id":"ab-u1-aptest","course":"ab","unit":"u1","title":"Unit 1 AP-style test · multiple choice","kind":"test","minutes":47,"lesson":null,"items":[{"q":"$\\displaystyle\\lim_{x\\to3}\\frac{x^2-9}{x^2-2x-3}$ is","c":["$0$","$\\dfrac32$","$3$","nonexistent"],"a":1,"e":"$\\dfrac{(x-3)(x+3)}{(x-3)(x+1)}=\\dfrac{x+3}{x+1}$ for $x\\neq3$, and $\\dfrac{6}{4}=\\dfrac32$.","calc":false,"topic":"1.6","img":[]},{"q":"$\\displaystyle\\lim_{x\\to0}\\frac{\\sqrt{x+9}-3}{x}$ is","c":["$0$","$\\dfrac13$","$\\dfrac16$","$3$"],"a":2,"e":"Multiply by the conjugate: $\\dfrac{(x+9)-9}{x\\left(\\sqrt{x+9}+3\\right)}=\\dfrac{1}{\\sqrt{x+9}+3}\\to\\dfrac16$.","calc":false,"topic":"1.6","img":[]},{"q":"$\\displaystyle\\lim_{x\\to0}\\frac{\\sin(5x)}{x}$ is","c":["$5$","$1$","$\\dfrac15$","$0$"],"a":0,"e":"$\\dfrac{\\sin5x}{x}=5\\cdot\\dfrac{\\sin5x}{5x}\\to5\\cdot1=5$.","calc":false,"topic":"1.8","img":[]},{"q":"$\\displaystyle\\lim_{x\\to\\infty}\\frac{4x^3-x}{2x^3+7x^2}$ is","c":["$0$","$\\dfrac47$","$\\infty$","$2$"],"a":3,"e":"Equal degrees: the limit is the ratio of the leading coefficients, $\\frac42=2$.","calc":false,"topic":"1.15","img":[]},{"q":"$\\displaystyle\\lim_{x\\to-\\infty}\\frac{2x}{\\sqrt{x^2+5}}$ is","c":["$2$","$-2$","$0$","$-\\infty$"],"a":1,"e":"For $x<0$, $\\sqrt{x^2+5}\\approx|x|=-x$, so the quotient approaches $\\dfrac{2x}{-x}=-2$.","calc":false,"topic":"1.15","img":[]},{"q":"$\\displaystyle\\lim_{x\\to2^-}\\frac{|x-2|}{x-2}$ is","c":["$1$","$0$","$-1$","nonexistent"],"a":2,"e":"For $x<2$, $|x-2|=-(x-2)$, so the quotient equals $-1$.","calc":false,"topic":"1.7","img":[]},{"q":"<div class=\"tbl\"><table><tr><td>$x$</td><td>$0.9$</td><td>$0.99$</td><td>$0.999$</td><td>$1.001$</td><td>$1.01$</td><td>$1.1$</td></tr><tr><td>$f(x)$</td><td>$2.71$</td><td>$2.97$</td><td>$2.997$</td><td>$3.003$</td><td>$3.03$</td><td>$3.31$</td></tr></table></div> Based on the table, which is the best estimate of $\\displaystyle\\lim_{x\\to1}f(x)$?","c":["$2.997$","$3$","$3.003$","The limit does not exist."],"a":1,"e":"The values approach $3$ from both the left and the right.","calc":false,"topic":"1.4","img":[]},{"q":"Let $f(x)=\\begin{cases}x^2+1, & x<1<br> 3x-1, & x\\ge1.\\end{cases}$ Which statement is true?","c":["$\\lim_{x\\to1}f(x)$ does not exist.","$\\lim_{x\\to1}f(x)$ exists, but $f$ is not continuous at $x=1$.","$f$ is continuous at $x=1$.","$f(1)$ is undefined."],"a":2,"e":"$\\lim_{x\\to1^-}f(x)=2$, $\\lim_{x\\to1^+}f(x)=2$ and $f(1)=3-1=2$. All three conditions of continuity hold.","calc":false,"topic":"1.11","img":[]},{"q":"For what value of $k$ is $f(x)=\\begin{cases}kx+3, & x\\le2<br> x^2-k, & x>2\\end{cases}$ continuous at $x=2$?","c":["$-\\dfrac13$","$\\dfrac13$","$1$","$7$"],"a":1,"e":"Left: $2k+3$. Right: $4-k$. Then $2k+3=4-k$, so $3k=1$ and $k=\\frac13$.","calc":false,"topic":"1.13","img":[]},{"q":"What type of discontinuity does $g(x)=\\dfrac{x^2-4}{x-2}$ have at $x=2$?","c":["Jump","Infinite","Removable","None; $g$ is continuous at $x=2$."],"a":2,"e":"$g(2)$ is undefined, but $\\lim_{x\\to2}g(x)=\\lim_{x\\to2}(x+2)=4$ exists: a removable discontinuity.","calc":false,"topic":"1.10","img":[]},{"q":"Which line or lines are vertical asymptotes of the graph of $h(x)=\\dfrac{x+1}{x^2-1}$?","c":["$x=1$ only","$x=-1$ only","$x=1$ and $x=-1$","$y=0$ only"],"a":0,"e":"$h(x)=\\dfrac{x+1}{(x-1)(x+1)}=\\dfrac{1}{x-1}$ for $x\\neq-1$. At $x=-1$ there is a hole (the limit is $-\\frac12$); at $x=1$ the one-sided limits are infinite. $y=0$ is a horizontal asymptote.","calc":false,"topic":"1.14","img":[]},{"q":"$\\displaystyle\\lim_{x\\to0}x^2\\cos\\!\\left(\\frac1x\\right)$ is","c":["$1$","$0$","$-1$","nonexistent"],"a":1,"e":"$-x^2\\le x^2\\cos\\frac1x\\le x^2$ and both bounds approach $0$. By the squeeze theorem, the limit is $0$.","calc":false,"topic":"1.8","img":[]},{"q":"The function $f$ is continuous on $[1,5]$ with $f(1)=-2$ and $f(5)=6$. Which statement must be true?","c":["$f(c)=8$ for some $c$ in $(1,5)$.","$f(3)=2$.","$f$ is increasing on $[1,5]$.","$f(c)=4$ for some $c$ in $(1,5)$."],"a":3,"e":"$4$ is between $-2$ and $6$, and $f$ is continuous, so the IVT guarantees such a $c$. Nothing forces $f(3)=2$ or monotonicity, and $8$ is not between the endpoint values.","calc":false,"topic":"1.16","img":[]},{"q":"$\\displaystyle\\lim_{x\\to\\infty}\\frac{3e^x+x^2}{e^x-1}$ is","c":["$0$","$1$","$3$","$\\infty$"],"a":2,"e":"$e^x$ dominates $x^2$ and constants as $x\\to\\infty$. Dividing by $e^x$: $\\dfrac{3+x^2e^{-x}}{1-e^{-x}}\\to\\dfrac{3+0}{1-0}=3$.","calc":false,"topic":"1.15","img":[]},{"q":"Which of the following limits does <b>not</b> exist?","c":["$\\displaystyle\\lim_{x\\to1}g(x)$","$\\displaystyle\\lim_{x\\to-1^+}g(x)$","$\\displaystyle\\lim_{x\\to-1}g(x)$","$\\displaystyle\\lim_{x\\to4}g(x)$"],"a":2,"e":"At $x=-1$ the left-hand limit is $2$ and the right-hand limit is $0$. The other limits are $2$, $0$ and $0$.","calc":false,"topic":"1.3 \\textbullet\\ graph","img":["f5b4f961ea90.svg"]},{"q":"What is $\\displaystyle\\lim_{x\\to1}g(x)$?","c":["$4$","$2$","$1$","It does not exist."],"a":1,"e":"Both pieces approach the open circle at $(1,2)$. The filled dot $g(1)=4$ does not affect the limit.","calc":false,"topic":"1.3 \\textbullet\\ graph","img":["f5b4f961ea90.svg"]},{"q":"Which statement about the behavior of $g$ near $x=3$ is true?","c":["$\\lim_{x\\to3^-}g(x)=+\\infty$ and $\\lim_{x\\to3^+}g(x)=-\\infty$","$\\lim_{x\\to3^-}g(x)=-\\infty$ and $\\lim_{x\\to3^+}g(x)=+\\infty$","$\\lim_{x\\to3}g(x)=+\\infty$","$\\lim_{x\\to3}g(x)=2$"],"a":0,"e":"To the left of $x=3$ the graph rises without bound; to the right it falls without bound.","calc":false,"topic":"1.14 \\textbullet\\ graph","img":["f5b4f961ea90.svg"]},{"q":"At which value of $x$ does $g$ have a removable discontinuity?","c":["$x=-1$","$x=3$","$x=-4$","$x=1$"],"a":3,"e":"At $x=1$, $\\lim_{x\\to1}g(x)=2$ exists but $g(1)=4$. At $x=-1$ the discontinuity is a jump; at $x=3$ it is infinite.","calc":false,"topic":"1.10 \\textbullet\\ graph","img":["f5b4f961ea90.svg"]},{"q":"What is $\\displaystyle\\lim_{x\\to0}g\\big(g(x)\\big)$?","c":["$1$","$4$","$2$","It does not exist."],"a":2,"e":"As $x\\to0$, $g(x)=x+1\\to1$, taking values close to $1$ but not equal to $1$ (from below when $x<0$, from above when $x>0$). As the input approaches $1$ from either side, $g$ approaches $2$. So the limit is $2$, not $g(1)=4$.","calc":false,"topic":"1.9 \\textbullet\\ graph","img":["f5b4f961ea90.svg"]},{"q":"Using a table of values or a graph, what is $\\displaystyle\\lim_{x\\to0}\\frac{2^x-1}{x}$, to three decimal places?","c":["$0.500$","$0.693$","$1.000$","$1.443$"],"a":1,"e":"Values at $x=\\pm0.001$ are about $0.6929$ and $0.6934$, so the limit is about $0.693$ (it equals $\\ln2$).","calc":true,"topic":"1.4","img":[]},{"q":"How many values of $c$ in the open interval $(0,2)$ satisfy $c^3-4c+1=0$?","c":["None","One","Two","Three"],"a":2,"e":"Graphing $y=x^3-4x+1$ shows zeros at $x\\approx-2.115$, $0.254$ and $1.861$. Two of them are in $(0,2)$.","calc":true,"topic":"1.16","img":[]}]}];
